INSERT INTO `bg_goi_thau` (`id`,`so_thong_bao`,`ten_goi_thau`,`noi_dung`,`ngay_phat_hanh`,`thoi_gian_mo_bao_gia`,`thoi_gian_dong_bao_gia`,`han_cuoi`,`thoi_gian_hop_dong`,`hieu_luc_bao_gia`,`token`,`trang_thai`,`ngay_tao`,`ngay_cap_nhat`,`nguoi_tao`,`nguoi_cap_nhat`,`da_xoa`) VALUES
('1','5742/2026','Mua vật tư tiêu hao phẫu thuật cột sống và thần kinh sọ não năm 2026','Nẹp tạo hình bản sống cổ lối sau; Vít tạo hình bản sống cổ lối sau; Van dẫn lưu dịch não tủy ổ bụng có kèm catheter phủ kháng sinh','2026-08-14','2026-08-14 23:22:48','2026-08-28 17:19:44','2026-08-27','24','180','4b14d46c6c519fdedd9fe2cb925c433d','1','2026-08-17 23:22:48','2026-08-19 22:22:17','1','1','0'),
('2','5800/2026','Mua vật tư nha khoa và dụng cụ phẫu thuật răng miệng năm 2026','Hộp đựng mũi khoan; Bộ que hàn Composite; Cây nạo nha chu GRACEY các số','2026-07-28','2026-07-28 23:22:48','2026-08-15 17:00:00','2026-08-15','12','120','308992e600a3149333a6450a115fe8ab','1','2026-08-17 23:22:48','2026-08-17 23:22:48','1','1','0');
INSERT INTO `bg_hang_hoa` (`id`,`goi_thau_id`,`ma_hh`,`ten_phan`,`stt_theo_phan`,`stt_thong_bao`,`ten_hang_hoa`,`thong_so_ky_thuat`,`chung_nhan`,`yeu_cau_xuat_xu`,`dvt`,`so_luong`,`yeu_cau_tro_cu`,`thu_tu`,`ngay_tao`,`ngay_cap_nhat`,`nguoi_tao`,`nguoi_cap_nhat`,`da_xoa`) VALUES
('1','1','HH001','Phần 1','P1.1','1','Nẹp tạo hình bản sống cổ lối sau','Vật liệu: Hợp kim Titan hoặc Titan hoặc Cobalt Chrome hoặc vật liệu tương đương về độ bền cơ lý\nHình thái nẹp phù hợp với vị trí mở cung sau\nChiều dài các cỡ từ ≤ 8mm đến ≥ 16mm, bước tăng ≤ 2mm\nCó ≥ 4 lỗ bắt vít.','FDA (Mỹ) hoặc MHLW/PMDA (Nhật Bản) hoặc CE (MDR)','Nhóm G7, Liên minh Châu Âu (EU), Úc','Cái','100.000','Cam kết cung cấp trợ cụ đầy đủ, chính hãng (trợ cụ được cung cấp bởi nhà sản xuất hoặc có xác nhận của nhà sản xuất về tính tương thích với hàng hoá dự thầu) đáp ứng đầy đủ nhu cầu chuyên môn','1','2026-08-17 23:22:48','2026-08-20 22:28:45','1','1','0'),
('2','1','HH002','Phần 1','P1.2','2','Vít tạo hình bản sống cổ lối sau','Vật liệu: Hợp kim Titan hoặc Titan hoặc Cobalt Chrome hoặc vật liệu tương đương về độ bền cơ lý\nTự taro\nĐường kính các cỡ ≥ 2,5mm\nChiều dài các cỡ từ ≤ 6mm đến ≥ 8mm\nTương thích với nẹp tạo hình bản sống cổ sau','FDA (Mỹ) hoặc MHLW/PMDA (Nhật Bản) hoặc CE (MDR)','Nhóm G7, Liên minh Châu Âu (EU), Úc','Cái','300.000','Cam kết cung cấp trợ cụ đầy đủ, chính hãng (trợ cụ được cung cấp bởi nhà sản xuất hoặc có xác nhận của nhà sản xuất về tính tương thích với hàng hoá dự thầu) đáp ứng đầy đủ nhu cầu chuyên môn','2','2026-08-17 23:22:48','2026-08-20 22:28:45','1','1','0'),
('3','1','HH003','Phần 2','P2.1','3','Van dẫn lưu dịch não tủy ổ bụng có kèm catheter phủ kháng sinh','Bộ van dùng để dẫn lưu dịch não tủy ổ bụng, có kèm catheter phủ kháng sinh\nĐóng gói tiệt trùng bao gồm:\n- 01 Van bằng Polysulfone hoặc tương đương. Có các loại van tương đương với từng mức áp lực khác nhau\n- 01 Catheter não thất được phủ kháng sinh. Kích thước: đường kính trong ≥ 1,3mm, đường kính ngoài ≥ 2,5mm, chiều dài ≥ 23 cm.\n- 01 Catheter dẫn lưu xuống ổ bụng được phủ kháng sinh. Kích thước: đường kính trong ≥ 1,3mm, đường kính ngoài ≥ 2,5mm, chiều dài  ≥ 120 cm','FDA (Mỹ) hoặc MHLW/PMDA (Nhật Bản) hoặc CE (MDR)','Nhóm G7, Liên minh Châu Âu (EU), Úc','Cái','50.000',NULL,'3','2026-08-17 23:22:48','2026-08-20 22:28:45','1','1','0'),
('4','1','HH004','Phần 3','P3.1','4','Bộ vật tư dùng trong điều trị đau thần kinh sử dụng sóng cao tần','Bộ vật tư dùng trong điều trị đau thần kinh sử dụng sóng cao tần, tối thiểu bao gồm:\n- Điện cực đốt:\n+ Chiều dài gồm tối thiểu 4 cỡ trong khoảng từ 50mm- 200mm\n+ Đường kính gồm tối thiểu 4 cỡ trong khoảng 20G - 23G\n+ Có các chế độ đốt 3 trong 1 \n+ Có các chế độ đốt RF/PRF và STP Pulsed RF (sóng cao tần xung ngắn quãng ngẫu nhiên). \n- Kim tích hợp dây cáp điện kết nối đến máy đốt','FDA (Mỹ) hoặc MHLW/PMDA (Nhật Bản) hoặc ARTG (Úc) hoặc CE (MDD/MDR)','Nhóm G7, Liên minh Châu Âu (EU), Úc','Bộ','100.000','Cam kết cung cấp trợ cụ đầy đủ, chính hãng (trợ cụ được cung cấp bởi nhà sản xuất hoặc có xác nhận của nhà sản xuất về tính tương thích với hàng hoá dự thầu) đáp ứng đầy đủ nhu cầu chuyên môn','4','2026-08-17 23:22:48','2026-08-20 22:28:45','1','1','0'),
('5','1','HH005','Phần 4','P4.1','5','Lưỡi cắt đốt bằng sóng cao tần dùng trong nội soi cột sống 2 cổng, loại dùng bên ngoài ống tủy sống','Lưỡi cắt đốt sử dụng sóng cao tần, có thể cắt, đốt và cầm máu ở nhiệt độ kiểm soát 40-70 độ \nĐầu đốt tạo với thân chính góc ≥ 70 độ \nĐường kính đầu đốt ≥ 4mm\nChiều dài thân ≥ 135mm\nĐóng gói tiệt trùng','FDA (Mỹ) hoặc MHLW/PMDA (Nhật Bản) hoặc ARTG (Úc) hoặc CE (MDD/MDR)','Nhóm G7, Liên minh Châu Âu (EU), Úc','Cái','250.000','Cam kết cung cấp trợ cụ đầy đủ, chính hãng (trợ cụ được cung cấp bởi nhà sản xuất hoặc có xác nhận của nhà sản xuất về tính tương thích với hàng hoá dự thầu) đáp ứng đầy đủ nhu cầu chuyên môn','5','2026-08-17 23:22:48','2026-08-20 22:28:45','1','1','0'),
('6','1','HH006','Phần 4','P4.2','6','Lưỡi cắt đốt bằng sóng cao tần đầu uốn được dùng trong nội soi cột sống 2 cổng, loại dùng bên trong ống tủy sống','Lưỡi cắt đốt sử dụng sóng cao tần, có thể cắt, đốt và cầm máu ở nhiệt độ kiểm soát 40-70 độ \nĐầu lưỡi có thể uốn được\nĐường kính đầu đốt ≤ 4mm\nChiều dài thân trong khoảng từ 80mm - 140mm\nĐóng gói tiệt trùng','FDA (Mỹ) hoặc MHLW/PMDA (Nhật Bản) hoặc ARTG (Úc) hoặc CE (MDD/MDR)','Nhóm G7, Liên minh Châu Âu (EU), Úc','Cái','250.000','Cam kết cung cấp trợ cụ đầy đủ, chính hãng (trợ cụ được cung cấp bởi nhà sản xuất hoặc có xác nhận của nhà sản xuất về tính tương thích với hàng hoá dự thầu) đáp ứng đầy đủ nhu cầu chuyên môn','6','2026-08-17 23:22:48','2026-08-20 22:28:45','1','1','0'),
('7','1','HH007','Phần 4','P4.3','7','Dây nước dùng trong phẫu thuật nội soi cột sống 2 cổng','Chất liệu PVC hoặc silicon hoặc tương đương\nThiết kế bao gồm tối thiểu 02 đầu nhọn nối vào bình đựng nước, 01 đầu nối vào ống soi, 01 đầu nối vào nắp đậy.\nĐóng gói tiệt trùng','FDA (Mỹ) hoặc MHLW/PMDA (Nhật Bản) hoặc ARTG (Úc) hoặc CE (MDD/MDR)','Nhóm G7, Liên minh Châu Âu (EU), Úc','Cái','250.000','Cam kết cung cấp trợ cụ đầy đủ, chính hãng (trợ cụ được cung cấp bởi nhà sản xuất hoặc có xác nhận của nhà sản xuất về tính tương thích với hàng hoá dự thầu) đáp ứng đầy đủ nhu cầu chuyên môn','7','2026-08-17 23:22:48','2026-08-20 22:28:45','1','1','0'),
('8','1','HH008','Phần 4','P4.4','8','Mũi mài dùng trong phẫu thuật nội soi cột sống 2 cổng','Thiết kế đầu mũi mài hình cầu có phủ kim cương\nChất liệu thép không gỉ hoặc tương đương\nĐường kính đầu mũi mài các cỡ từ ≤ 1mm đến ≥ 5mm\nChiều dài các cỡ trong khoảng từ 35mm - 45mm\nĐóng gói tiệt trùng','FDA (Mỹ) hoặc MHLW/PMDA (Nhật Bản) hoặc ARTG (Úc) hoặc CE (MDD/MDR)','Nhóm G7, Liên minh Châu Âu (EU), Úc','Cái','250.000','Cam kết cung cấp trợ cụ đầy đủ, chính hãng (trợ cụ được cung cấp bởi nhà sản xuất hoặc có xác nhận của nhà sản xuất về tính tương thích với hàng hoá dự thầu) đáp ứng đầy đủ nhu cầu chuyên môn','8','2026-08-17 23:22:48','2026-08-20 22:28:45','1','1','0'),
('9','1','HH009','Phần 4','P4.5','9','Lưỡi cắt đốt bằng sóng cao tần đầu dạng móc câu dùng trong nội soi cột sống 2 cổng, loại dùng bên trong ống tủy sống','Lưỡi cắt đốt sử dụng sóng cao tần, có thể cắt, đốt và cầm máu ở nhiệt độ kiểm soát 40-70 độ \nĐầu lưỡi dạng móc câu\nĐường kính đầu đốt ≤ 4mm\nChiều dài thân trong khoảng từ 80mm - 140mm\nĐóng gói tiệt trùng','FDA (Mỹ) hoặc MHLW/PMDA (Nhật Bản) hoặc ARTG (Úc) hoặc CE (MDD/MDR)','Nhóm G7, Liên minh Châu Âu (EU), Úc','Cái','50.000','Cam kết cung cấp trợ cụ đầy đủ, chính hãng (trợ cụ được cung cấp bởi nhà sản xuất hoặc có xác nhận của nhà sản xuất về tính tương thích với hàng hoá dự thầu) đáp ứng đầy đủ nhu cầu chuyên môn','9','2026-08-17 23:22:48','2026-08-20 22:28:45','1','1','0'),
